-- 0014: คลังเสียงราคา (เหมือนคลังชื่อคอนโด: อ่านเฉพาะราคาที่มีในลีด แล้วเก็บไฟล์ไว้ใช้ซ้ำ)
create table if not exists public.price_audio (
  price         bigint primary key,
  tts_text      text,
  path          text,
  audio_source  text,
  tts_error     text,
  generated_at  timestamptz,
  updated_at    timestamptz not null default now()
);
alter table public.price_audio enable row level security;
drop policy if exists team_all_price_audio on public.price_audio;
create policy team_all_price_audio on public.price_audio for all to authenticated using (public.is_team()) with check (public.is_team());
create index if not exists leads_rent_idx on public.leads (rent);

-- ราคาไม่ซ้ำจากไฟล์ Price - asset (434 ราคา)
on conflict (price) do nothing;
